package com.bank.reference;

class ReferenceGenerator {

    // Manual two-pointer reversal on a char array.
    String reverseManual(String s) {
        if (s == null) throw new IllegalArgumentException("null string");
        char[] chars = s.toCharArray();     // mutable copy
        int left = 0, right = chars.length - 1;
        while (left < right) {
            char temp = chars[left];
            chars[left] = chars[right];
            chars[right] = temp;
            left++;
            right--;
        }
        return new String(chars);           // new reversed String
    }

    // Built-in: StringBuilder.reverse handles surrogate pairs correctly.
    String reverseBuiltIn(String s) {
        if (s == null) throw new IllegalArgumentException("null string");
        return new StringBuilder(s).reverse().toString();
    }
}
